  if (uMode && __Porffor_regex_pAt(start) == 123) { // {
    let i: i32 = start + 1;
    let v: i32 = 0;
    let digits: i32 = 0;
    while (true) {
      const c: i32 = __Porffor_regex_pAt(i);
      if (c == 125) break; // }
      const h: i32 = __Porffor_regex_hexVal(c);
      if (h < 0) return -1;
      v = v * 16 + h;
      if (v > 0x10FFFF) return -1;
      digits += 1;
      i += 1;
    }
    if (digits == 0) return -1;
    __Porffor_regex_pPos = i + 1;
    return v;
  }

