  let v: i32 = 0;
  for (let i: i32 = 0; i < 4; i++) {
    const h: i32 = __Porffor_regex_hexVal(__Porffor_regex_pAt(start + i));
    if (h < 0) return -1;
    v = v * 16 + h;
  }
  __Porffor_regex_pPos = start + 4;

  // \u lead + \u trail merge into one cp in u mode
